use std::path::{Path, PathBuf};
use std::sync::Arc;

use futures::StreamExt;
use tokio::fs;
use tokio::io::AsyncReadExt;
use tracing::warn;
use serde::Serialize;

/// Controls how workspace instances observe each other's writes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum WorkspaceMode {
    /// Multiple handles on the same root see each other's writes (default).
    #[default]
    Shared,
    /// Writes from one handle are invisible to others (stub — returns errors).
    Isolated,
}

#[derive(thiserror::Error, Debug)]
pub enum WorkspaceError {
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    #[error("Path outside workspace root: {path}")]
    PathTraversal { path: PathBuf },

    #[error("Isolated workspace does not support this operation")]
    Isolated,

    #[error("Tool execution failed: {0}")]
    ToolFailed(String),
}

/// Represents a single search match.
#[derive(Debug, Clone, Serialize)]
pub struct SearchMatch {
    pub file_path: PathBuf,
    pub line_number: usize,
    pub line_content: String,
}

/// Result of a workspace search operation.
#[derive(Debug, Clone, Serialize)]
pub struct SearchResult {
    pub matches: Vec<SearchMatch>,
    pub total_count: usize,
}

/// Metadata about a file in the workspace.
#[derive(Debug, Clone, Serialize)]
pub struct FileInfo {
    pub path: PathBuf,
    pub size_bytes: u64,
    pub is_directory: bool,
}

/// Progress event emitted during long-running tool operations.
#[derive(Debug, Clone, Serialize)]
pub struct ToolProgress {
    pub tool_call_id: String,
    pub phase: ProgressPhase,
    pub message: String,
}

#[derive(Debug, Clone, Serialize)]
pub enum ProgressPhase {
    Started,
    Streaming,
    Completed,
    Failed,
}

/// Result of a tool execution.
#[derive(Debug, Clone, Serialize)]
pub struct ToolResult {
    pub tool_call_id: String,
    pub success: bool,
    pub content: String,
}

/// Abstract workspace access for tools.
#[async_trait::async_trait]
pub trait Workspace: Send + Sync {
    fn root(&self) -> &Path;
    fn mode(&self) -> WorkspaceMode;

    /// Read a file relative to the workspace root.
    async fn read(&self, relative_path: &str) -> Result<String, WorkspaceError>;

    /// Write (replace) a file relative to the workspace root.
    async fn write(&self, relative_path: &str, content: &str) -> Result<(), WorkspaceError>;

    /// Search for `query` (case-insensitive substring) in all UTF-8 text files.
    async fn search(&self, query: &str) -> Result<SearchResult, WorkspaceError>;

    /// List files recursively (up to `max_depth`, 0 = unlimited).
    async fn list_files(&self, max_depth: usize) -> Result<Vec<FileInfo>, WorkspaceError>;
}

use std::path::{Path, PathBuf};
use std::sync::Arc;

use futures::StreamExt;
use tokio::fs;
use tokio::io::AsyncReadExt;
use tracing::{info, warn};

use crate::workspace::{
    Workspace, WorkspaceError, SearchResult, SearchMatch, FileInfo,
    ToolProgress, ToolResult, ProgressPhase,
};

/// Filesystem-backed workspace. All paths are resolved relative to `root`.
///
/// Path traversal defense: any `..` component that would escape `root`
/// returns `WorkspaceError::PathTraversal`.
pub struct FsWorkspace {
    root: PathBuf,
    mode: crate::workspace::WorkspaceMode,
}

impl FsWorkspace {
    pub fn new(root: PathBuf) -> Self {
        Self {
            root,
            mode: crate::workspace::WorkspaceMode::Shared,
        }
    }

    pub fn with_mode(mut self, mode: crate::workspace::WorkspaceMode) -> Self {
        self.mode = mode;
        self
    }

    /// Resolve a relative path to an absolute path rooted at `self.root`.
    ///
    /// Returns `WorkspaceError::PathTraversal` if the resolved path escapes
    /// the workspace root.
    fn resolve_path(&self, relative: &str) -> Result<PathBuf, WorkspaceError> {
        // Reject paths that try to escape via `..` components.
        let candidate = self.root.join(relative);
        let canonical = candidate.canonicalize().unwrap_or(candidate.clone());

        // Ensure the canonical path starts with the canonical root.
        let canonical_root = self.root.canonicalize().unwrap_or(self.root.clone());
        if !canonical.starts_with(&canonical_root) {
            return Err(WorkspaceError::PathTraversal { path: candidate });
        }

        Ok(canonical)
    }
}

#[async_trait::async_trait]
impl Workspace for FsWorkspace {
    fn root(&self) -> &Path {
        &self.root
    }

    fn mode(&self) -> crate::workspace::WorkspaceMode {
        self.mode
    }

    async fn read(&self, relative_path: &str) -> Result<String, WorkspaceError> {
        let absolute = self.resolve_path(relative_path)?;
        let mut file = fs::File::open(&absolute).await?;
        let mut contents = String::new();
        file.read_to_string(&mut contents).await?;
        Ok(contents)
    }

    async fn write(&self, relative_path: &str, content: &str) -> Result<(), WorkspaceError> {
        if self.mode == crate::workspace::WorkspaceMode::Isolated {
            return Err(WorkspaceError::Isolated);
        }

        let absolute = self.resolve_path(relative_path)?;

        // Ensure parent directory exists.
        if let Some(parent) = absolute.parent() {
            fs::create_dir_all(parent).await?;
        }

        fs::write(&absolute, content).await?;
        info!(path = %relative_path, "wrote file to workspace");
        Ok(())
    }

    async fn search(&self, query: &str) -> Result<SearchResult, WorkspaceError> {
        let mut matches = Vec::new();
        let query_lower = query.to_lowercase();

        let mut entries = fs::read_dir(&self.root).await?;
        Self::search_dir(
            &self.root,
            &self.root,
            &query_lower,
            &mut matches,
        )
        .await?;

        matches.sort_by(|a, b| a.file_path.cmp(&b.file_path).then(a.line_number.cmp(&b.line_number)));

        Ok(SearchResult {
            total_count: matches.len(),
            matches,
        })
    }

    async fn list_files(&self, max_depth: usize) -> Result<Vec<FileInfo>, WorkspaceError> {
        let mut files = Vec::new();
        Self::list_dir(&self.root, 0, max_depth, &mut files).await?;
        Ok(files)
    }
}

impl FsWorkspace {
    /// Recursively walk a directory, searching for `query` in UTF-8 text files.
    async fn search_dir(
        root: &Path,
        dir: &Path,
        query: &str,
        matches: &mut Vec<SearchMatch>,
    ) -> Result<(), WorkspaceError> {
        let mut entries = fs::read_dir(dir).await?;
        while let Some(entry) = entries.next_entry().await? {
            let path = entry.path();
            let meta = entry.metadata().await?;

            if meta.is_dir() {
                Self::search_dir(root, &path, query, matches).await?;
            } else if meta.is_file() {
                if let Some(ext) = path.extension() {
                    let text_ext = matches!(
                        ext.to_string_lossy().as_ref(),
                        "txt" | "rs" | "toml" | "yaml" | "yml" | "json" | "md"
                            | "sh" | "py" | "js" | "ts" | "toml" | "lock" | "cfg"
                            | "ini" | "conf" | "env" | "log" | "csv" | "html"
                            | "css" | "xml" | "svg"
                    );

                    if !text_ext {
                        continue;
                    }
                }

                if let Ok(contents) = fs::read_to_string(&path).await {
                    for (idx, line) in contents.lines().enumerate() {
                        if line.to_lowercase().contains(query) {
                            matches.push(SearchMatch {
                                file_path: path.strip_prefix(root).unwrap_or(path.clone()).to_path_buf(),
                                line_number: idx + 1,
                                line_content: line.to_string(),
                            });
                        }
                    }
                }
            }
        }
        Ok(())
    }

    async fn list_dir(
        dir: &Path,
        depth: usize,
        max_depth: usize,
        out: &mut Vec<FileInfo>,
    ) -> Result<(), WorkspaceError> {
        if max_depth > 0 && depth > max_depth {
            return Ok(());
        }

        let mut entries = fs::read_dir(dir).await?;
        while let Some(entry) = entries.next_entry().await? {
            let meta = entry.metadata().await?;
            let path = entry.path();
            let rel = path.strip_prefix(dir).unwrap_or(path.clone());

            out.push(FileInfo {
                path: rel,
                size_bytes: meta.len(),
                is_directory: meta.is_dir(),
            });

            if meta.is_dir() {
                Self::list_dir(&path, depth + 1, max_depth, out).await?;
            }
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[tokio::test]
    async fn fs_workspace_read_write_roundtrip() {
        let dir = tempdir().unwrap();
        let ws = FsWorkspace::new(dir.path().to_path_buf());

        ws.write("hello.txt", "world\n").await.unwrap();
        let contents = ws.read("hello.txt").await.unwrap();
        assert_eq!(contents, "world\n");
    }

    #[tokio::test]
    async fn fs_workspace_blocks_path_traversal() {
        let dir = tempdir().unwrap();
        let ws = FsWorkspace::new(dir.path().to_path_buf());

        let result = ws.read("../../etc/passwd").await;
        assert!(matches!(result, Err(WorkspaceError::PathTraversal { .. })));
    }

    #[tokio::test]
    async fn fs_workspace_search_finds_matches() {
        let dir = tempdir().unwrap();
        fs::write(dir.path().join("greeting.rs"), "fn hello() { println!(\"hi\"); }").await.unwrap();

        let ws = FsWorkspace::new(dir.path().to_path_buf());
        let result = ws.search("println").await.unwrap();

        assert_eq!(result.total_count, 1);
        assert_eq!(result.matches[0].file_path, PathBuf::from("greeting.rs"));
        assert_eq!(result.matches[0].line_number, 1);
    }
}

// workspace.rs — moved to harness-workspace crate.
// Re-export for backward compat (will be removed after all crates updated).
pub use harness_workspace::Workspace;
pub use harness_workspace::WorkspaceMode;
pub use harness_workspace::WorkspaceError;
pub use harness_workspace::SearchResult;
pub use harness_workspace::FileInfo;
pub use harness_workspace::ToolProgress;
pub use harness_workspace::ToolResult;

// ToolExecutor and ToolRegistry traits remain here for now (migrated in T3).

/// A workspace stub that pretends writes are invisible to other handles.
/// Permits reads; rejects writes with [`WorkspaceError::Isolated`].
///
/// In a future phase this will be backed by a temporary copy-on-write
/// tree. For now it exists to satisfy the capability surface.
pub struct IsolatedWorkspace {
    inner: Arc<dyn Workspace>,
}

impl IsolatedWorkspace {
    pub fn new(inner: Arc<dyn Workspace>) -> Self {
        Self { inner }
    }
}

#[async_trait::async_trait]
impl Workspace for IsolatedWorkspace {
    fn root(&self) -> &Path {
        self.inner.root()
    }

    fn mode(&self) -> WorkspaceMode {
        WorkspaceMode::Isolated
    }

    async fn read(&self, relative_path: &str) -> Result<String, WorkspaceError> {
        self.inner.read(relative_path).await
    }

    async fn write(&self, _relative_path: &str, _content: &str) -> Result<(), WorkspaceError> {
        Err(WorkspaceError::Isolated)
    }

    async fn search(&self, query: &str) -> Result<SearchResult, WorkspaceError> {
        self.inner.search(query).await
    }

    async fn list_files(&self, max_depth: usize) -> Result<Vec<FileInfo>, WorkspaceError> {
        self.inner.list_files(max_depth).await
    }
}

#[cfg(test)]
mod isolated_tests {
    use super::*;
    use tempfile::tempdir;

    #[tokio::test]
    async fn isolated_workspace_allows_reads() {
        let dir = tempdir().unwrap();
        fs::write(dir.path().join("data.txt"), "secret").await.unwrap();

        let shared = FsWorkspace::new(dir.path().to_path_buf());
        let isolated = IsolatedWorkspace::new(Arc::new(shared));

        let contents = isolated.read("data.txt").await.unwrap();
        assert_eq!(contents, "secret");
    }

    #[tokio::test]
    async fn isolated_workspace_rejects_writes() {
        let dir = tempdir().unwrap();
        let shared = FsWorkspace::new(dir.path().to_path_buf());
        let isolated = IsolatedWorkspace::new(Arc::new(shared));

        let result = isolated.write("data.txt", "new content").await;
        assert!(matches!(result, Err(WorkspaceError::Isolated)));
    }
}

