/// Input for the `workspace.search` tool.
#[derive(Debug, Clone, Deserialize, JsonSchema)]
pub struct SearchInput {
    /// The search query (case-insensitive substring match).
    pub query: String,
}

/// Searches all text files in the workspace for the given query.
pub struct SearchTool {
    workspace: Arc<dyn Workspace>,
}

impl SearchTool {
    pub fn new(workspace: Arc<dyn Workspace>) -> Self {
        Self { workspace }
    }
}

impl SearchTool {
    fn descriptor() -> ToolDescriptor {
        ToolDescriptor {
            id: "workspace.search".to_string(),
            name: "workspace.search".to_string(),
            description: "Search all text files in the workspace for a query string".to_string(),
            input_schema: serde_json::to_value(
                <SearchInput as JsonSchema>::json_schema()
            ).unwrap_or(serde_json::json!({})),
        }
    }
}

#[async_trait::async_trait]
impl ToolExecutor for SearchTool {
    fn descriptor(&self) -> ToolDescriptor {
        Self::descriptor()
    }

    async fn execute(
        &self,
        input: serde_json::Value,
        token: CancellationToken,
    ) -> ExecutionResult {
        let input: SearchInput = match serde_json::from_value(input) {
            Ok(v) => v,
            Err(e) => {
                return ExecutionResult {
                    success: false,
                    content: String::new(),
                    failure: Some(ExecutionFailure {
                        kind: FailureKind::InvalidInput,
                        message: e.to_string(),
                    }),
                    usage: None,
                };
            }
        };

        if token.is_cancelled() {
            return ExecutionResult::cancelled();
        }

        info!(query = %input.query, "workspace.search: searching");

        match self.workspace.search(&input.query).await {
            Ok(result) => {
                let content = if result.matches.is_empty() {
                    format!("No matches found for query '{}'", input.query)
                } else {
                    let mut lines = vec![
                        format!("{} matches found for '{}':", result.total_count, input.query),
                    ];
                    for m in &result.matches {
                        let rel = m.file_path.display();
                        lines.push(format!("  {}:{}: {}", rel, m.line_number, m.line_content));
                    }
                    lines.join("\n")
                };
                ExecutionResult {
                    success: true,
                    content,
                    failure: None,
                    usage: None,
                }
            }
            Err(e) => ExecutionResult {
                success: false,
                content: String::new(),
                failure: Some(ExecutionFailure {
                    kind: FailureKind::WorkspaceError,
                    message: e.to_string(),
                }),
                usage: None,
            },
        }
    }
}

