/// Input for the `shell.exec` tool.
#[derive(Debug, Clone, Deserialize, JsonSchema)]
pub struct ExecInput {
    /// The shell command to run.
    pub command: String,
    /// Arguments passed to the command.
    #[serde(default)]
    pub args: Vec<String>,
    /// Working directory (relative to workspace root). Defaults to workspace root.
    #[serde(default)]
    pub cwd: Option<String>,
    /// Maximum time in seconds before the command is killed.
    #[serde(default)]
    pub timeout_secs: Option<u64>,
}

/// Executes a shell command using `tokio::process::Command`.
///
/// Features:
/// - Streams stdout/stderr line-by-line as `ToolProgress` events.
/// - Kills the child process when `CancellationToken` is triggered.
/// - Optional timeout enforced via `tokio::time::timeout`.
pub struct ExecTool {
    // TODO: inject in future; for Phase 4, workspace isn't needed for shell exec.
}

impl ExecTool {
    pub fn new() -> Self {
        Self
    }
}

impl ExecTool {
    fn descriptor() -> ToolDescriptor {
        ToolDescriptor {
            id: "shell.exec".to_string(),
            name: "shell.exec".to_string(),
            description: "Execute a shell command".to_string(),
            input_schema: serde_json::to_value(
                <ExecInput as JsonSchema>::json_schema()
            ).unwrap_or(serde_json::json!({})),
        }
    }
}

#[async_trait::async_trait]
impl ToolExecutor for ExecTool {
    fn descriptor(&self) -> ToolDescriptor {
        Self::descriptor()
    }

    async fn execute(
        &self,
        input: serde_json::Value,
        token: CancellationToken,
    ) -> ExecutionResult {
        let input: ExecInput = match serde_json::from_value(input) {
            Ok(v) => v,
            Err(e) => {
                return fail(FailureKind::InvalidInput, e.to_string());
            }
        };

        if token.is_cancelled() {
            return fail(FailureKind::Cancelled, "tool call was cancelled".to_string());
        }

        info!(command = %input.command, args = ?input.args, "shell.exec: running command");

        let mut cmd = tokio::process::Command::new(&input.command);
        cmd.args(&input.args)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());

        if let Some(ref cwd) = input.cwd {
            cmd.current_dir(cwd);
        }

        let mut child = match cmd.spawn() {
            Ok(c) => c,
            Err(e) => {
                return fail(FailureKind::ExecutionError, format!("failed to spawn: {e}"));
            }
        };

        // Store child handle so we can kill it on cancellation.
        let child_handle = Arc::new(Mutex::new(Some(child)));

        // Clone the handle for the cancel watcher.
        let child_for_cancel = child_handle.clone();
        let cancel_handle = tokio::spawn(async move {
            loop {
                if token.is_cancelled() {
                    if let Ok(Some(mut child)) = child_for_cancel.lock().unwrap().take() {
                        let _ = child.kill().await;
                    }
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(100)).await;
            }
        });

        // Read stdout/stderr concurrently.
        let stdout = child.stdout.take().unwrap();
        let stderr = child.stderr.take().unwrap();

        let (tx_out, mut rx_out) = tokio::sync::mpsc::unbounded_channel();
        let (tx_err, mut rx_err) = tokio::sync::mpsc::unbounded_channel();

        let _stdout_task = tokio::spawn(async move {
            let mut reader = tokio::io::BufReader::new(stdout);
            let mut line = String::new();
            loop {
                line.clear();
                match reader.read_line(&mut line).await {
                    Ok(0) => break,
                    Ok(_) => { let _ = tx_out.send(line.clone()); }
                    Err(_) => break,
                }
            }
        });

        let _stderr_task = tokio::spawn(async move {
            let mut reader = tokio::io::BufReader::new(stderr);
            let mut line = String::new();
            loop {
                line.clear();
                match reader.read_line(&mut line).await {
                    Ok(0) => break,
                    Ok(_) => { let _ = tx_err.send(line.clone()); }
                    Err(_) => break,
                }
            }
        });

        // Wait for child to finish, with optional timeout.
        let exit_status = if let Some(timeout_secs) = input.timeout_secs {
            tokio::time::timeout(
                std::time::Duration::from_secs(timeout_secs),
                child.wait(),
            ).await
        } else {
            child.wait().await
        };

        // Stop the cancel watcher.
        cancel_handle.abort();

        let _ = child_handle.lock().unwrap().take();

        // Drain remaining stdout/stderr output.
        let mut all_stdout = String::new();
        let mut all_stderr = String::new();
        while let Ok(line) = rx_out.try_recv() {
            all_stdout.push_str(&line);
        }
        while let Ok(line) = rx_err.try_recv() {
            all_stderr.push_str(&line);
        }

        match exit_status {
            Ok(status) if status.success() => {
                info!(status = "success", "shell.exec: command completed");
                ExecutionResult {
                    success: true,
                    content: all_stdout,
                    failure: None,
                    usage: None,
                }
            }
            Ok(status) => {
                let code = status.code().unwrap_or(-1);
                warn!(status = %code, "shell.exec: command exited with error");
                ExecutionResult {
                    success: false,
                    content: all_stderr,
                    failure: Some(ExecutionFailure {
                        kind: FailureKind::ExecutionError,
                        message: format!("command exited with code {}", code),
                    }),
                    usage: None,
                }
            }
            Err(e) => {
                warn!(error = %e, "shell.exec: command failed to wait");
                ExecutionResult {
                    success: false,
                    content: all_stderr,
                    failure: Some(ExecutionFailure {
                        kind: FailureKind::ExecutionError,
                        message: e.to_string(),
                    }),
                    usage: None,
                }
            }
        }
    }
}

// --- helpers ---

fn fail(kind: FailureKind, message: String) -> ExecutionResult {
    ExecutionResult {
        success: false,
        content: String::new(),
        failure: Some(ExecutionFailure { kind, message }),
        usage: None,
    }
}

use std::sync::Arc;

use harness_tools::registry::{ToolRegistry, ToolDescriptor};

/// Evaluates whether a tool call should be allowed, require approval, or be denied.
#[derive(Debug, Clone, Default)]
pub struct PermissionPolicy;

/// Result of a permission evaluation.
pub enum PermissionOutcome {
    /// No restriction — the executor may run the tool.
    Allow,
    /// The caller must obtain user approval before executing.
    RequiresApproval(String),
    /// The tool is blocked by policy.
    Denied(String),
}

impl PermissionPolicy {
    /// Check whether a tool with `tool_id` may be executed for an agent
    /// whose `enabled_tool_ids` and `tool_permissions` describe the allowed tools.
    pub fn evaluate(
        &self,
        enabled_tool_ids: &[String],
        tool_permissions: &[(String, PermissionMode)],
        tool_id: &str,
    ) -> PermissionOutcome {
        if !enabled_tool_ids.contains(&tool_id.to_string()) {
            return PermissionOutcome::Denied(format!(
                "tool '{}' is not enabled for this agent",
                tool_id
            ));
        }

        let mode = tool_permissions.iter()
            .find(|(id, _)| id == tool_id)
            .map(|(_, m)| m.clone())
            .unwrap_or(PermissionMode::Allow);

        match mode {
            PermissionMode::Allow => PermissionOutcome::Allow,
            PermissionMode::Ask(reason) => PermissionOutcome::RequiresApproval(reason),
            PermissionMode::Deny => PermissionOutcome::Denied(format!(
                "tool '{}' is denied by policy", tool_id
            )),
        }
    }
}

pub async fn execute_tool(
    &self,
    call_id: &str,
    tool_id: &str,
    input: serde_json::Value,
    capabilities: &AgentCapabilities,
    toolset: &AgentToolset,
) -> agent_interface::ToolResult {
    use crate::permissions::PermissionPolicy;

    // ── Layer 1: Capability check ──────────────────────────────────────
    if !capabilities.is_tool_enabled(tool_id) {
        return agent_interface::ToolResult {
            call_id: call_id.to_string(),
            success: false,
            content: format!(
                "Tool '{}' is not enabled for this agent. Available tools: {}",
                tool_id,
                capabilities.enabled_tool_ids().join(", "),
            ),
        };
    }

    // ── Layer 2: Permission policy check ──────────────────────────────
    let decision = PermissionPolicy.evaluate(
        capabilities.enabled_tool_ids(),
        toolset.permission_overrides(),
        tool_id,
    );

    match decision {
        PermissionOutcome::Denied(reason) => {
            return agent_interface::ToolResult {
                call_id: call_id.to_string(),
                success: false,
                content: format!("Tool '{}' is blocked by policy: {reason}", tool_id),
            };
        }
        PermissionOutcome::RequiresApproval(reason) => {
            // Emit RequestPermission effect — existing flow in harness-core
            // handles the rest (suspend at WaitingForPermission, wait for
            // ApprovePermission/RejectPermission).
            //
            // In the agent runner, this means we return a special result that
            // the core transitions map to a RequestPermission effect.
            return agent_interface::ToolResult {
                call_id: call_id.to_string(),
                success: false,
                content: format!("Approval required for '{}': {reason}", tool_id),
                // TODO: surface a flag that the core interprets as
                // AgentEffect::RequestPermission instead of ToolFailed.
            };
        }
        PermissionOutcome::Allow => {} // fall through to execution
    }

    // ── Layer 3: Dispatch to executor ──────────────────────────────────
    let executor = self.registry.get_executor(tool_id);
    match executor {
        Some(exec) => {
            let cancellation = CancellationToken::new();
            let exec_result = exec.execute(input, cancellation).await;
            agent_interface::ToolResult {
                call_id: call_id.to_string(),
                success: exec_result.success,
                content: exec_result.content,
            }
        }
        None => agent_interface::ToolResult {
            call_id: call_id.to_string(),
            success: false,
            content: format!("Tool '{}' not found in registry", tool_id),
        },
    }
}

