//! Tool traits, types, registries, and descriptors.
//!
//! This crate provides the core abstractions for tool execution in the
//! harness: [`ToolExecutor`], [`ToolRegistry`], [`SimpleToolRegistry`],
//! and the associated data types ([`ExecutionResult`], [`ToolDescriptor`],
//! [`CancellationToken`], etc.).

pub mod executor;
pub mod registry;

pub use executor::{
    CancellationToken, ExecutionFailure, ExecutionResult, FailureKind, ProgressPhase,
    ToolDescriptor, ToolExecutor, ToolId, ToolInput, ToolProgress, ToolUsage,
};
pub use registry::{RegistrationError, SimpleToolRegistry, ToolRegistry};

use std::sync::Arc;

use schemars::JsonSchema;
use serde::Serialize;

/// Unique identifier for a tool within a session.
pub type ToolId = String;

/// Lightweight cooperative cancellation token.
#[derive(Clone, Default)]
pub struct CancellationToken {
    cancelled: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

impl CancellationToken {
    pub fn new() -> Self {
        Self {
            cancelled: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
        }
    }

    pub fn cancel(&self) {
        self.cancelled.store(true, std::sync::atomic::Ordering::SeqCst);
    }

    pub fn is_cancelled(&self) -> bool {
        self.cancelled.load(std::sync::atomic::Ordering::SeqCst)
    }
}

/// The input payload shape for a tool, generated from its JSON schema.
#[derive(Debug, Clone, Serialize, JsonSchema)]
#[serde(untagged)]
pub struct ToolInput {
    /// Raw JSON value of the tool's input parameters.
    pub raw: serde_json::Value,
}

/// Structured failure returned from a tool executor.
#[derive(Debug, Clone, Serialize)]
pub struct ExecutionFailure {
    pub kind: FailureKind,
    pub message: String,
}

#[derive(Debug, Clone, Serialize)]
pub enum FailureKind {
    InvalidInput,
    WorkspaceError,
    ExecutionError,
    Timeout,
    Cancelled,
}

/// Result of a tool execution.
#[derive(Debug, Clone, Serialize)]
pub struct ExecutionResult {
    pub success: bool,
    pub content: String,
    pub failure: Option<ExecutionFailure>,
    pub usage: Option<ToolUsage>,
}

impl ExecutionResult {
    pub fn cancelled() -> Self {
        Self {
            success: false,
            content: String::new(),
            failure: Some(ExecutionFailure {
                kind: FailureKind::Cancelled,
                message: "tool call was cancelled".to_string(),
            }),
            usage: None,
        }
    }
}

/// Token/compute usage reported by a tool (if applicable).
#[derive(Debug, Clone, Serialize, Default)]
pub struct ToolUsage {
    pub prompt_tokens: u64,
    pub completion_tokens: u64,
}

/// Progress event streamed during long-running tool execution.
#[derive(Debug, Clone, Serialize)]
pub struct ToolProgress {
    pub tool_call_id: ToolId,
    pub phase: ProgressPhase,
    pub message: String,
}

#[derive(Debug, Clone, Serialize)]
pub enum ProgressPhase {
    Started,
    Streaming,
    Completed,
    Failed,
}

/// Describes a tool — its name, description, and JSON input schema.
#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct ToolDescriptor {
    pub id: ToolId,
    pub name: String,
    pub description: String,
    /// JSON Schema (as a `serde_json::Value`). Used for `schemars::JsonSchema`
    /// generation and model-facing tool registration.
    pub input_schema: serde_json::Value,
}

/// Executes a single tool invocation.
///
/// Implementors are expected to be `Clone` (to be shared via `Arc` in the
/// registry) and must honor `CancellationToken`.
#[async_trait::async_trait]
pub trait ToolExecutor: Send + Sync + Clone {
    /// Returns the tool descriptor (name, description, JSON schema).
    fn descriptor(&self) -> ToolDescriptor;

    /// Execute the tool with the given input and cancellation token.
    ///
    /// Returns [`ExecutionResult`] on completion. Must not panic — errors
    /// inside the tool must be surfaced as `ExecutionResult` values.
    async fn execute(
        &self,
        input: serde_json::Value,
        token: CancellationToken,
    ) -> ExecutionResult;
}

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use async_trait::async_trait;

use crate::executor::{ToolDescriptor, ToolExecutor, ToolId};

/// Describes how a registry must behave — enables mocking in tests.
#[async_trait]
pub trait ToolRegistry: Send + Sync {
    fn register(&self, executor: Arc<dyn ToolExecutor>) -> Result<(), RegistrationError>;
    fn get_executor(&self, tool_id: &str) -> Option<Arc<dyn ToolExecutor>>;
    fn descriptors(&self) -> Vec<ToolDescriptor>;
}

/// HashMap-backed concrete implementation.
pub struct SimpleToolRegistry {
    tools: Mutex<HashMap<ToolId, (ToolDescriptor, Arc<dyn ToolExecutor>)>>,
}

impl SimpleToolRegistry {
    pub fn new() -> Self {
        Self {
            tools: Mutex::new(HashMap::new()),
        }
    }

    /// Register a tool executor and its descriptor.
    ///
    /// Returns `Err` if a tool with the same `id` is already registered.
    pub fn register_tool(&self, executor: Arc<dyn ToolExecutor>) -> Result<(), RegistrationError> {
        let descriptor = executor.descriptor();
        let mut tools = self.tools.lock().unwrap();
        if tools.contains_key(&descriptor.id) {
            return Err(RegistrationError::DuplicateToolId(descriptor.id));
        }
        tools.insert(descriptor.id.clone(), (descriptor, executor));
        Ok(())
    }

    /// Look up a registered tool executor by ID.
    pub fn get_executor(&self, tool_id: &str) -> Option<Arc<dyn ToolExecutor>> {
        let tools = self.tools.lock().unwrap();
        tools.get(tool_id).map(|(_, executor)| executor.clone())
    }

    /// Return descriptors for all registered tools (for model-facing registration).
    pub fn descriptors(&self) -> Vec<ToolDescriptor> {
        let tools = self.tools.lock().unwrap();
        tools
            .values()
            .map(|(descriptor, _)| descriptor.clone())
            .collect()
    }

    /// Check whether a tool ID is registered.
    pub fn contains(&self, tool_id: &str) -> bool {
        let tools = self.tools.lock().unwrap();
        tools.contains_key(tool_id)
    }
}

#[async_trait]
impl ToolRegistry for SimpleToolRegistry {
    fn register(&self, executor: Arc<dyn ToolExecutor>) -> Result<(), RegistrationError> {
        self.register_tool(executor)
    }

    fn get_executor(&self, tool_id: &str) -> Option<Arc<dyn ToolExecutor>> {
        self.get_executor(tool_id)
    }

    fn descriptors(&self) -> Vec<ToolDescriptor> {
        self.descriptors()
    }
}

#[derive(Debug, thiserror::Error)]
pub enum RegistrationError {
    #[error("tool with id '{0}' is already registered")]
    DuplicateToolId(String),
}

impl Default for SimpleToolRegistry {
    fn default() -> Self {
        Self::new()
    }
}

