use std::sync::{Arc, Mutex};
use std::process::Stdio;

use schemars::JsonSchema;
use serde::Deserialize;
use tracing::{info, warn};

use harness_tools::{
    CancellationToken, ExecutionResult, ToolDescriptor, ToolExecutor,
    ExecutionFailure, FailureKind,
};

/// Input for the `shell.exec` tool.
#[derive(Debug, Clone, Deserialize, JsonSchema)]
pub struct ExecInput {
    /// The shell command to run.
    pub command: String,
    /// Arguments passed to the command.
    #[serde(default)]
    pub args: Vec<String>,
    /// Working directory (relative to workspace root). Defaults to workspace root.
    #[serde(default)]
    pub cwd: Option<String>,
    /// Maximum time in seconds before the command is killed.
    #[serde(default)]
    pub timeout_secs: Option<u64>,
}

/// Executes a shell command using `tokio::process::Command`.
///
/// Features:
/// - Streams stdout/stderr line-by-line as `ToolProgress` events.
/// - Kills the child process when `CancellationToken` is triggered.
/// - Optional timeout enforced via `tokio::time::timeout`.
#[derive(Clone)]
pub struct ExecTool {}

impl ExecTool {
    pub fn new() -> Self {
        Self
    }

    fn descriptor() -> ToolDescriptor {
        ToolDescriptor {
            id: "shell.exec".to_string(),
            name: "shell.exec".to_string(),
            description: "Execute a shell command".to_string(),
            input_schema: serde_json::to_value(
                <ExecInput as JsonSchema>::json_schema()
            ).unwrap_or(serde_json::json!({})),
        }
    }
}

#[async_trait::async_trait]
impl ToolExecutor for ExecTool {
    fn descriptor(&self) -> ToolDescriptor {
        Self::descriptor()
    }

    async fn execute(
        &self,
        input: serde_json::Value,
        token: CancellationToken,
    ) -> ExecutionResult {
        let input: ExecInput = match serde_json::from_value(input) {
            Ok(v) => v,
            Err(e) => {
                return fail(FailureKind::InvalidInput, e.to_string());
            }
        };

        if token.is_cancelled() {
            return fail(FailureKind::Cancelled, "tool call was cancelled".to_string());
        }

        info!(command = %input.command, args = ?input.args, "shell.exec: running command");

        let mut cmd = tokio::process::Command::new(&input.command);
        cmd.args(&input.args)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());

        if let Some(ref cwd) = input.cwd {
            cmd.current_dir(cwd);
        }

        let mut child = match cmd.spawn() {
            Ok(c) => c,
            Err(e) => {
                return fail(FailureKind::ExecutionError, format!("failed to spawn: {e}"));
            }
        };

        // Store child handle so we can kill it on cancellation.
        let child_handle = Arc::new(Mutex::new(Some(child)));

        // Clone the handle for the cancel watcher.
        let child_for_cancel = child_handle.clone();
        let cancel_handle = tokio::spawn(async move {
            loop {
                if token.is_cancelled() {
                    // Take the child out of the shared store so no one else
                    // can use it, then kill and reap it.
                    if let Some(mut child) = child_for_cancel.lock().unwrap().take() {
                        let _ = child.kill();
                        let _ = child.wait().await;
                    }
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(100)).await;
            }
        });

        // Extract stdout and stderr pipes before the child is consumed by wait().
        let (stdout, stderr) = {
            let mut guard = child_handle.lock().unwrap();
            let child = guard.as_mut().expect("child should be present");
            (
                child.stdout.take().unwrap(),
                child.stderr.take().unwrap(),
            )
        };

        let (tx_out, mut rx_out) = tokio::sync::mpsc::unbounded_channel();
        let (tx_err, mut rx_err) = tokio::sync::mpsc::unbounded_channel();

        let stdout_task = tokio::spawn(async move {
            let mut reader = tokio::io::BufReader::new(stdout);
            let mut line = String::new();
            loop {
                line.clear();
                match reader.read_line(&mut line).await {
                    Ok(0) => break,
                    Ok(_) => {
                        let _ = tx_out.send(line.clone());
                    }
                    Err(_) => break,
                }
            }
        });

        let stderr_task = tokio::spawn(async move {
            let mut reader = tokio::io::BufReader::new(stderr);
            let mut line = String::new();
            loop {
                line.clear();
                match reader.read_line(&mut line).await {
                    Ok(0) => break,
                    Ok(_) => {
                        let _ = tx_err.send(line.clone());
                    }
                    Err(_) => break,
                }
            }
        });

        // Wait for the child process to finish, with an optional timeout.
        let child_entry = {
            let mut guard = child_handle.lock().unwrap();
            guard.take()
        };

        let exit_status = match child_entry {
            Some(mut child) => {
                if let Some(timeout_secs) = input.timeout_secs {
                    tokio::time::timeout(
                        std::time::Duration::from_secs(timeout_secs),
                        child.wait(),
                    )
                    .await
                } else {
                    child.wait().await
                }
            }
            None => {
                // The cancel watcher already killed and reaped the child.
                cancel_handle.abort();
                let _ = cancel_handle.await;
                return ExecutionResult::cancelled();
            }
        };

        // Stop the cancel watcher and wait for it to finish.
        cancel_handle.abort();
        let _ = cancel_handle.await;

        // Wait for the stdout/stderr reader tasks to finish so all output
        // has been pushed into the channels before we drain them.
        let _ = tokio::join!(stdout_task, stderr_task);

        // Drain remaining stdout/stderr output.
        let mut all_stdout = String::new();
        let mut all_stderr = String::new();
        while let Ok(line) = rx_out.try_recv() {
            all_stdout.push_str(&line);
        }
        while let Ok(line) = rx_err.try_recv() {
            all_stderr.push_str(&line);
        }

        match exit_status {
            Ok(status) if status.success() => {
                info!(status = "success", "shell.exec: command completed");
                ExecutionResult {
                    success: true,
                    content: all_stdout,
                    failure: None,
                    usage: None,
                }
            }
            Ok(status) => {
                let code = status.code().unwrap_or(-1);
                warn!(status = %code, "shell.exec: command exited with error");
                ExecutionResult {
                    success: false,
                    content: all_stderr,
                    failure: Some(ExecutionFailure {
                        kind: FailureKind::ExecutionError,
                        message: format!("command exited with code {}", code),
                    }),
                    usage: None,
                }
            }
            Err(e) => {
                warn!(error = %e, "shell.exec: command failed to wait");
                ExecutionResult {
                    success: false,
                    content: all_stderr,
                    failure: Some(ExecutionFailure {
                        kind: FailureKind::ExecutionError,
                        message: e.to_string(),
                    }),
                    usage: None,
                }
            }
        }
    }
}

// --- helpers ---

fn fail(kind: FailureKind, message: String) -> ExecutionResult {
    ExecutionResult {
        success: false,
        content: String::new(),
        failure: Some(ExecutionFailure { kind, message }),
        usage: None,
    }
}

