//! Tool trait, types, and placeholder tool stubs.
//!
//! This module defines the [`ToolExecutor`] trait — the contract every tool
//! implementation must satisfy — along with the data types it uses
//! ([`ToolDescriptor`], [`ToolId`], [`ToolCall`], [`ToolResult`],
//! [`ToolError`], [`CancellationToken`]).
//!
//! ## Stub tools
//!
//! The module also includes minimal placeholder implementations
//! ([`ReadTool`], [`EditTool`], [`SearchTool`], [`ExecTool`],
//! [`UnknownTool`]) so that [`SessionBuilder::toolset`] can wire tools
//! before the concrete `tools/filesystem` and `tools/shell` crates are
//! populated.  These stubs will be replaced by the real implementations once
//! those crates are complete.

use async_trait::async_trait;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Re-export `CancellationToken` from tokio-util so consumers don't need a
/// direct dependency on that crate.
pub use tokio_util::sync::CancellationToken;

// ---------------------------------------------------------------------------
// ToolId
// ---------------------------------------------------------------------------

/// Unique identifier for a tool within the harness-tools type system.
///
/// This type is distinct from [`harness_protocol::ids::ToolId`] — it is a
/// lightweight string-based identifier that matches the `name` field used in
/// tool calls (e.g. `"fs.read"`, `"shell.exec"`).
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
pub struct ToolId(pub String);

impl ToolId {
    /// Create a new `ToolId` from a string.
    pub fn new(id: impl Into<String>) -> Self {
        Self(id.into())
    }

    /// Return the inner string as a `&str`.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for ToolId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.0.fmt(f)
    }
}

impl From<String> for ToolId {
    fn from(s: String) -> Self {
        Self(s)
    }
}

impl From<&str> for ToolId {
    fn from(s: &str) -> Self {
        Self(s.to_string())
    }
}

// ---------------------------------------------------------------------------
// ToolDescriptor
// ---------------------------------------------------------------------------

/// Describes a tool — its identity, human-readable name, description, and
/// input JSON Schema.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ToolDescriptor {
    /// Machine-readable identifier (e.g. `"fs.read"`).
    pub id: ToolId,
    /// Human-readable name shown to the model/user.
    pub name: String,
    /// Description of what the tool does.
    pub description: String,
    /// JSON Schema for the tool's input arguments.
    pub input_schema: serde_json::Value,
}

// ---------------------------------------------------------------------------
// ToolInput
// ---------------------------------------------------------------------------

/// Typed input extracted from a [`ToolCall`]'s JSON arguments, used by
/// concrete tool implementations.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ToolInput {
    /// The raw JSON arguments.
    pub arguments: serde_json::Value,
}

impl ToolInput {
    /// Deserialize the arguments into the requested type.
    pub fn parse<T: serde::de::DeserializeOwned>(&self) -> Result<T, serde_json::Error> {
        serde_json::from_value(self.arguments.clone())
    }
}

// ---------------------------------------------------------------------------
// ToolResult
// ---------------------------------------------------------------------------

/// The (non-error) result produced by executing a tool.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResult {
    /// The call identifier this result corresponds to.
    pub call_id: String,
    /// JSON output produced by the tool.
    pub output: serde_json::Value,
    /// Whether the tool execution resulted in a logical error (as opposed to
    /// an infrastructure error reported via [`ToolError`]).
    pub is_error: bool,
}

// ---------------------------------------------------------------------------
// ToolError
// ---------------------------------------------------------------------------

/// Errors that can occur during tool execution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ToolError {
    /// The tool call failed during execution.
    ExecutionFailed,
    /// The tool is not permitted for the caller.
    PermissionDenied,
    /// The tool call timed out.
    Timeout,
    /// An internal / unexpected error occurred.
    Internal,
}

// ---------------------------------------------------------------------------
// ToolProgress
// ---------------------------------------------------------------------------

/// Streaming progress information emitted by long-running tool executions.
#[derive(Debug, Clone, Serialize)]
pub struct ToolProgress {
    /// A human-readable status message.
    pub status: String,
    /// A fraction between 0.0 and 1.0 indicating completion.
    pub fraction: f64,
}

// ---------------------------------------------------------------------------
// ToolExecutor trait
// ---------------------------------------------------------------------------

/// The contract every tool must implement.
///
/// Tools are stateless from the harness's perspective — any state they need
/// (e.g. a `Workspace` reference) is captured at construction time.
#[async_trait]
pub trait ToolExecutor: Send + Sync {
    /// Return the static descriptor for this tool.
    fn descriptor(&self) -> ToolDescriptor;

    /// Execute the tool with the given input.
    ///
    /// # Cancellation
    ///
    /// When `cancel` is triggered the tool should stop work as soon as
    /// practical and return [`ToolError::Timeout`].
    async fn execute(
        &self,
        input: ToolInput,
        cancel: CancellationToken,
    ) -> Result<ToolResult, ToolError>;
}

// ===========================================================================
// Stub tool implementations (Phase 4 placeholders)
// ===========================================================================
//
// The following types are **stubs** that implement [`ToolExecutor`] so that
// [`SessionBuilder::toolset`] (in `harness-engine`) can wire the builder
// before the concrete tool crates (`tools/filesystem`, `tools/shell`) are
// populated.  They will be replaced with real implementations later.
//
// Each stub returns a hard-coded "tool not yet implemented" error.

// ── Stub filesystem tools ────────────────────────────────────────────────

