### `crates/harness-tools/src/registry.rs` (new)

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use async_trait::async_trait;

use crate::executor::{ToolDescriptor, ToolExecutor, ToolId, ToolResult, ToolProgress, CancellationToken};

/// Concrete, HashMap-backed tool registry — replaces the old trait-based
/// `ToolRegistry` from `harness-runtime`.
///
/// Thread-safe (all methods take `&self`). Registered tools are stored as
/// `(ToolDescriptor, Arc<dyn ToolExecutor>)` pairs keyed by tool ID.
pub struct SimpleToolRegistry {
    tools: Mutex<HashMap<ToolId, (ToolDescriptor, Arc<dyn ToolExecutor>)>>,
}

impl SimpleToolRegistry {
    pub fn new() -> Self {
        Self {
            tools: Mutex::new(HashMap::new()),
        }
    }

    /// Register a tool executor and its descriptor.
    ///
    /// Returns `Err` if a tool with the same `id` is already registered.
    pub fn register_tool(&self, executor: Arc<dyn ToolExecutor>) -> Result<(), RegistrationError> {
        let descriptor = executor.descriptor();
        let mut tools = self.tools.lock().unwrap();
        if tools.contains_key(&descriptor.id) {
            return Err(RegistrationError::DuplicateToolId(descriptor.id));
        }
        tools.insert(descriptor.id.clone(), (descriptor, executor));
        Ok(())
    }

    /// Look up a registered tool executor by ID.
    pub fn get(&self, tool_id: &str) -> Option<Arc<dyn ToolExecutor>> {
        let tools = self.tools.lock().unwrap();
        tools.get(tool_id).map(|(_, executor)| executor.clone())
    }

    /// Return descriptors for all registered tools (for model-facing registration).
    pub fn descriptors(&self) -> Vec<ToolDescriptor> {
        let tools = self.tools.lock().unwrap();
        tools.values()
            .map(|(descriptor, _)| descriptor.clone())
            .collect()
    }

    /// Check whether a tool ID is registered.
    pub fn contains(&self, tool_id: &str) -> bool {
        let tools = self.tools.lock().unwrap();
        tools.contains_key(tool_id)
    }
}

#[derive(Debug, thiserror::Error)]
pub enum RegistrationError {
    #[error("tool with id '{0}' is already registered")]
    DuplicateToolId(String),
}

impl Default for SimpleToolRegistry {
    fn default() -> Self {
        Self::new()
    }
}
```

