### `crates/harness-runtime/src/permissions.rs` (new)

```rust
use harness_tools::registry::ToolRegistry;
use harness_core::agent::{AgentCapabilities, AgentToolset, PermissionMode};

/// Evaluates whether a tool call should be allowed, ask for confirmation, or be denied.
///
/// This is the "defender" step in the tool execution pipeline — it sits between
/// the incoming `ToolCallRequested` event and the actual executor dispatch.
#[derive(Debug, Clone, Default)]
pub struct PermissionPolicy;

/// The outcome of evaluating a tool call against the agent's policy.
pub enum PermissionDecision {
    /// Allow immediately — proceed to execution.
    Allow,
    /// Ask for permission — the agent runner should emit
    /// `AgentEffect::RequestPermission` and wait for a response.
    Ask(String), // reason
    /// Deny — return a synthetic failure without reaching the executor.
    Deny(String), // reason
}

impl PermissionPolicy {
    /// Decide whether a tool with `tool_id` should be executed for an agent
    /// with the given capabilities and toolset.
    pub fn evaluate(
        &self,
        capabilities: &AgentCapabilities,
        toolset: &AgentToolset,
        tool_id: &str,
    ) -> PermissionDecision {
        // 1. Capability check: agent must have the tool registered.
        if !capabilities.is_tool_enabled(tool_id) {
            return PermissionDecision::Deny(format!(
                "tool '{}' is not in the agent's capabilities",
                tool_id
            ));
        }

        // 2. Permission policy check: look up the tool's permission in the toolset.
        let mode = toolset.permission_for_tool(tool_id);
        match mode {
            PermissionMode::Allow => PermissionDecision::Allow,
            PermissionMode::Ask(reason) => PermissionDecision::Ask(reason),
            PermissionMode::Deny => PermissionDecision::Deny(format!(
                "tool '{}' is explicitly denied by policy",
                tool_id
            )),
        }
    }
}
```

