use std::sync::Arc;

use harness_tools::registry::{ToolRegistry, ToolDescriptor};

/// Evaluates whether a tool call should be allowed, require approval, or be denied.
#[derive(Debug, Clone, Default)]
pub struct PermissionPolicy;

/// Result of a permission evaluation.
pub enum PermissionOutcome {
    /// No restriction — the executor may run the tool.
    Allow,
    /// The caller must obtain user approval before executing.
    RequiresApproval(String),
    /// The tool is blocked by policy.
    Denied(String),
}

impl PermissionPolicy {
    /// Check whether a tool with `tool_id` may be executed for an agent
    /// whose `enabled_tool_ids` and `tool_permissions` describe the allowed tools.
    pub fn evaluate(
        &self,
        enabled_tool_ids: &[String],
        tool_permissions: &[(String, PermissionMode)],
        tool_id: &str,
    ) -> PermissionOutcome {
        if !enabled_tool_ids.contains(&tool_id.to_string()) {
            return PermissionOutcome::Denied(format!(
                "tool '{}' is not enabled for this agent",
                tool_id
            ));
        }

        let mode = tool_permissions.iter()
            .find(|(id, _)| id == tool_id)
            .map(|(_, m)| m.clone())
            .unwrap_or(PermissionMode::Allow);

        match mode {
            PermissionMode::Allow => PermissionOutcome::Allow,
            PermissionMode::Ask(reason) => PermissionOutcome::RequiresApproval(reason),
            PermissionMode::Deny => PermissionOutcome::Denied(format!(
                "tool '{}' is denied by policy", tool_id
            )),
        }
    }
}
```

