/// Verifies that the full session wiring composes correctly:
///
/// - A temp-directory workspace is created and a fixture file written.
/// - A [`SessionBuilder`] accepts the workspace, toolset, and backend.
/// - Calling [`SessionHandle::send`] with a prompt triggers the backend,
///   which replays a scripted `ToolCallRequested` → `Completed` sequence.
/// - The event stream contains [`AgentEvent::ToolCallRequested`].
/// - [`AgentEvent::ToolCallCompleted`] (if observed within the polling
///   window) appears after `ToolCallRequested`.
/// - The fixture file on disk is unmodified (the tool stubs return errors
///   without touching the filesystem).
///
/// This test exercises the **internal** stub tool executors created by
/// [`SessionBuilder::toolset`] via `build_executor_for()`.  Once real tool
/// implementations (harness-tool-filesystem, harness-tool-shell) are
/// populated, this test should be updated to wire them through the
/// builder's [`tools`](SessionBuilder::tools) method instead.
#[tokio::test]
async fn real_tools_e2e_tool_call_event_sequence() {
    // ── GIVEN ────────────────────────────────────────────
    let dir = tempdir().expect("tempdir should succeed");
    let fixture_path = dir.path().join("fixture.txt");
    tokio::fs::write(&fixture_path, "hello world")
        .await
        .expect("write fixture");

    // Use FakeWorkspace for now; replace with FsWorkspace when
    // harness-workspace/filesystem.rs is populated:
    //   use harness_workspace::FsWorkspace;
    //   let workspace: Arc<dyn Workspace> = Arc::new(FsWorkspace::new(dir.path().to_path_buf()));
    let workspace: Arc<dyn Workspace> = Arc::new(FakeWorkspace::new());

    // AgentToolset with all four tools enabled.
    let toolset = all_tools_toolset();

    // Backend that emits a ToolCallRequested for fs.read.
    let backend = make_tool_call_backend(
        "fs.read",
        serde_json::json!({ "path": "fixture.txt" }),
    );

    // ── WHEN — build session and send prompt ──────────────
    let session = SessionBuilder::new()
        .toolset(toolset, workspace)
        .backend(backend)
        .start()
        .await
        .expect("Session should build with toolset, workspace, and backend");

    let mut subscriber = session.subscribe();
    session
        .send("read the fixture file")
        .await
        .expect("sending a prompt should succeed");

    // ── Collect events ────────────────────────────────────
    // Limit iterations to prevent infinite looping from the stub tools'
    // error-return → backend-retry cycle (see `make_tool_call_backend` docs).
    let mut all_events: Vec<AgentEvent> = Vec::new();
    for _ in 0..30 {
        let batch = drain_events(&mut subscriber);
        if !batch.is_empty() {
            all_events.extend(batch);
        }
        // Stop if we observe a terminal Completed event.
        if all_events
            .iter()
            .any(|e| matches!(e, AgentEvent::Completed { .. }))
        {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }

    // ── THEN — validate event sequence ────────────────────

    // 1. ToolCallRequested must be present.
    let req_pos = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::ToolCallRequested { .. }));
    assert!(
        req_pos.is_some(),
        "Event stream must contain at least one ToolCallRequested;\n  got {} events: {:#?}",
        all_events.len(),
        all_events,
    );

    // 2. If ToolCallCompleted was also emitted within the polling window,
    //    it must appear after ToolCallRequested.  The stub executors return
    //    errors, so `has_error` should be `true`.
    if let Some(comp_pos) = all_events
        .iter()
        .position(|e| matches!(e, AgentEvent::ToolCallCompleted { .. }))
    {
        assert!(
            req_pos.unwrap() < comp_pos,
            "ToolCallRequested (at index {}) must precede ToolCallCompleted (at index {})",
            req_pos.unwrap(),
            comp_pos,
        );
    }

    // 3. The fixture file on disk retains its original content (the tool
    //    stubs do not perform real I/O).
    let content = tokio::fs::read_to_string(&fixture_path)
        .await
        .expect("fixture file should still exist");
    assert_eq!(
        content, "hello world",
        "The fixture file must be unmodified by the stub tool executors"
    );
}

/// Verifies that all four tool descriptors are properly registered in the
/// session's toolset and that the [`SessionBuilder`] accepts them without
/// error, even when no backend request is dispatched.
///
/// This test primarily validates the builder-level wiring rather than
/// the event stream.
#[tokio::test]
async fn session_builds_with_all_four_tools() {
    let dir = tempdir().expect("tempdir should succeed");
    let workspace: Arc<dyn Workspace> = Arc::new(FakeWorkspace::new());
    let toolset = all_tools_toolset();

    // A trivial backend that returns immediately with an end_turn result
    // (no tool calls, so the run completes cleanly).
    let request_id = RequestId::new();
    let backend = Arc::new(
        FakeBackend::new()
            .with_events(vec![
                ExecutionEvent::TextDelta {
                    request_id,
                    delta: "All tools are wired.".into(),
                },
                ExecutionEvent::Completed {
                    request_id,
                    result: ExecutionResult {
                        request_id,
                        usage: ModelUsage::default(),
                        cost: Cost::default(),
                        finish_reason: "end_turn".into(),
                    },
                },
            ])
            .with_result(ExecutionResult {
                request_id,
                usage: ModelUsage::default(),
                cost: Cost::default(),
                finish_reason: "end_turn".into(),
            }),
    );

    let session = SessionBuilder::new()
        .toolset(toolset, workspace)
        .backend(backend)
        .start()
        .await
        .expect("Session should build with all four tools");

    let mut subscriber = session.subscribe();

    session
        .send("check that all tools are available")
        .await
        .expect("send should succeed");

    // Collect events until we see a Completed event or time out.
    let mut all_events: Vec<AgentEvent> = Vec::new();
    for _ in 0..20 {
        let batch = drain_events(&mut subscriber);
        if !batch.is_empty() {
            all_events.extend(batch);
        }
        if all_events
            .iter()
            .any(|e| matches!(e, AgentEvent::Completed { outcome: AgentOutcome::Success }))
        {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }

    // The run should have completed successfully without any tool calls.
    let has_completed_success = all_events.iter().any(|e| {
        matches!(e, AgentEvent::Completed { outcome: AgentOutcome::Success })
    });
    assert!(
        has_completed_success,
        "Session should complete with Success outcome;\n  got events: {:#?}",
        all_events,
    );

    // No tool-call events should appear in a text-only backend round.
    let has_tool_request = all_events
        .iter()
        .any(|e| matches!(e, AgentEvent::ToolCallRequested { .. }));
    assert!(
        !has_tool_request,
        "No ToolCallRequested expected for an end_turn-only backend"
    );
}

