/// A [`ToolRegistry`] implementation that stores executors indexed by their
/// tool name (e.g. `"fs.read"`).
///
/// This is the concrete registry populated by
/// [`SessionBuilder::toolset`].  It implements
/// [`harness_runtime::traits::ToolRegistry`] so it can be passed directly
/// to [`SessionRuntime::new`].
struct SimpleToolRegistry {
    tools: HashMap<String, (harness_protocol::tools::ToolDescriptor, Arc<dyn ToolExecutor>)>,
}

impl SimpleToolRegistry {
    fn new() -> Self {
        Self {
            tools: HashMap::new(),
        }
    }

    fn register(
        &mut self,
        name: String,
        descriptor: harness_protocol::tools::ToolDescriptor,
        executor: Arc<dyn ToolExecutor>,
    ) {
        self.tools.insert(name, (descriptor, executor));
    }
}

#[async_trait]
impl ToolRegistry for SimpleToolRegistry {
    fn lookup(&self, name: &str) -> Option<Arc<dyn ToolExecutor>> {
        self.tools.get(name).map(|(_, executor)| executor.clone())
    }

    fn descriptors(&self) -> Vec<harness_protocol::tools::ToolDescriptor> {
        self.tools
            .values()
            .map(|(descriptor, _)| descriptor.clone())
            .collect()
    }
}

