/// Errors raised while configuring or operating a session.
#[derive(Debug, thiserror::Error)]
pub enum HarnessError {
    #[error("missing required field: backend")]
    MissingBackend,
    #[error("missing required field: tool_registry")]
    MissingToolRegistry,
    #[error("invalid integration configuration: {0}")]
    InvalidIntegrationConfig(#[from] serde_json::Error),
    #[error("integration error: {0}")]
    Integration(#[from] IntegrationError),
    #[error("session error: {0}")]
    Session(#[from] SessionError),
}

struct PendingIntegration {
    id: String,
    config: serde_json::Value,
}

/// Fluent builder for direct or registry-backed sessions.
pub struct SessionBuilder {
    backend: Option<Arc<dyn ExecutionBackend>>,
    integration: Option<PendingIntegration>,
    integrations: Arc<IntegrationRegistry>,
    tool_registry: Option<Arc<dyn ToolRegistry>>,
    workspace: Option<Arc<dyn Workspace>>,
    /// The toolset to inject into the root agent's capabilities.
    /// When set alongside `tool_registry`, the builder creates the registry
    /// from the toolset's enabled descriptors via `build_executor_for()`.
    root_toolset: Option<AgentToolset>,
}

impl SessionBuilder {
    /// Create a builder with an empty integration registry.
    pub fn new() -> Self {
        Self::with_integrations(Arc::new(IntegrationRegistry::new()))
    }

    /// Create a builder attached to a shared registry.
    pub fn with_integrations(integrations: Arc<IntegrationRegistry>) -> Self {
        Self {
            backend: None,
            integration: None,
            integrations,
            tool_registry: None,
            workspace: None,
            root_toolset: None,
        }
    }

    /// Inject an already constructed backend.
    pub fn backend(mut self, backend: Arc<dyn ExecutionBackend>) -> Self {
        self.backend = Some(backend);
        self.integration = None;
        self
    }

    /// Select a registered integration and provider-specific configuration.
    ///
    /// Resolution is deferred until [`start`](Self::start), keeping the fluent
    /// builder synchronous while allowing factories to perform async setup.
    pub fn integration<C: Serialize>(
        mut self,
        id: impl Into<String>,
        config: C,
    ) -> Result<Self, HarnessError> {
        self.integration = Some(PendingIntegration {
            id: id.into(),
            config: serde_json::to_value(config)?,
        });
        self.backend = None;
        Ok(self)
    }

    /// Set the session tool registry.
    pub fn tools(mut self, tool_registry: Arc<dyn ToolRegistry>) -> Self {
        self.tool_registry = Some(tool_registry);
        self
    }

    /// Set the workspace, defaulting to an empty in-memory workspace.
    pub fn workspace(mut self, workspace: Arc<dyn Workspace>) -> Self {
        self.workspace = Some(workspace);
        self
    }

    /// Register an `AgentToolset` into the session.
    ///
    /// This is an alternative to [`tools`](Self::tools) that takes a
    /// high-level tool policy set and a [`Workspace`] reference, creates
    /// the appropriate [`ToolExecutor`] instances via
    /// [`build_executor_for`](Self::build_executor_for), registers them
    /// into a [`SimpleToolRegistry`], and wires both the registry and the
    /// toolset into the root agent's capabilities.
    ///
    /// When this method is used, the builder will automatically populate
    /// the tool registry — there is no need to also call [`tools`](Self::tools).
    ///
    /// The `workspace` argument provides the [`Workspace`] that filesystem
    /// tools (`fs.read`, `fs.edit`, `workspace.search`) will delegate to.
    /// Shell tools (`shell.exec`) ignore the workspace.
    pub fn toolset(mut self, toolset: AgentToolset, workspace: Arc<dyn Workspace>) -> Self {
        // 1. Register all tool executors into the registry.
        let mut registry = SimpleToolRegistry::new();
        for descriptor in toolset.enabled_descriptors() {
            let executor = self.build_executor_for(descriptor, workspace.clone());
            registry.register(descriptor.name.clone(), descriptor.clone(), executor);
        }

        // 2. Wire the registry + toolset into the root Agent's capabilities.
        self.tool_registry = Some(Arc::new(registry));
        self.root_toolset = Some(toolset);
        self.workspace = Some(workspace);
        self
    }

    /// Build the appropriate executor for a given tool descriptor.
    ///
    /// Maps known descriptor ID strings to concrete tool implementations.
    /// Unknown descriptors get an [`UnknownTool`] fallback that always
    /// returns [`ProtocolToolError::ExecutionFailed`].
    ///
    /// At present (Phase 4 stubs) all tools return
    /// [`ProtocolToolError::ExecutionFailed`].  Once the real
    /// `tools/filesystem` and `tools/shell` crates are populated, the match
    /// arms below will delegate to `ReadTool::new(workspace)`,
    /// `EditTool::new(workspace)`, `SearchTool::new(workspace)`, and
    /// `ExecTool::new()` respectively.
    fn build_executor_for(
        &self,
        descriptor: &harness_protocol::tools::ToolDescriptor,
        _workspace: Arc<dyn Workspace>,
    ) -> Arc<dyn ToolExecutor> {
        match descriptor.name.as_str() {
            "fs.read" => Arc::new(ReadTool),
            "fs.edit" => Arc::new(EditTool),
            "workspace.search" => Arc::new(SearchTool),
            "shell.exec" => Arc::new(ExecTool),
            _ => Arc::new(UnknownTool {
                _name: descriptor.name.clone(),
            }),
        }
    }

    /// Resolve configuration and create the live session.
    pub async fn start(self) -> Result<SessionHandle, HarnessError> {
        let backend = match (self.backend, self.integration) {
            (Some(backend), _) => backend,
            (None, Some(integration)) => {
                self.integrations
                    .create(&integration.id, integration.config)
                    .await?
            }
            (None, None) => return Err(HarnessError::MissingBackend),
        };
        let tool_registry = self
            .tool_registry
            .ok_or(HarnessError::MissingToolRegistry)?;
        let backend: Arc<dyn ExecutionBackend> = Arc::new(ToolAdvertisingBackend {
            inner: backend,
            tools: tool_registry.descriptors(),
        });
        let workspace: Arc<dyn Workspace> = self
            .workspace
            .unwrap_or_else(|| Arc::new(FakeWorkspace::new()));
        let session_id = SessionId::new();
        let (event_tx, _) = broadcast::channel(256);
        let event_sink = Arc::new(BroadcastEventSink {
            tx: event_tx.clone(),
        });
        let runtime = Arc::new(SessionRuntime::new(
            session_id,
            backend,
            tool_registry,
            workspace,
            event_sink,
        ));

        Ok(SessionHandle {
            client: SessionClient::new(runtime),
            session_id,
        })
    }
}

impl Default for SessionBuilder {
    fn default() -> Self {
        Self::new()
    }
}

/// Handle to a live session.
pub struct SessionHandle {
    client: SessionClient,
    session_id: SessionId,
}

impl SessionHandle {
    pub async fn send(&self, prompt: &str) -> Result<(), HarnessError> {
        self.client
            .send(SessionCommand::Prompt(UserInput {
                text: prompt.to_string(),
                attachments: vec![],
            }))
            .await?;
        Ok(())
    }

    pub fn subscribe(&self) -> broadcast::Receiver<AgentEventEnvelope> {
        self.client.subscribe()
    }

    pub fn snapshot(&self) -> SessionSnapshot {
        self.client.snapshot()
    }

    pub fn session_id(&self) -> SessionId {
        self.session_id
    }
}

//! Tool registry types — [`ToolRegistry`] trait and [`SimpleToolRegistry`] impl.
//!
//! The [`ToolRegistry`] trait defines how tool executors are looked up by
//! their identifier string.  [`SimpleToolRegistry`] is the canonical
//! HashMap-backed implementation.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use async_trait::async_trait;

use crate::executor::{ToolDescriptor, ToolExecutor, ToolId};

/// Describes how a registry must behave — enables mocking in tests.
#[async_trait]
pub trait ToolRegistry: Send + Sync {
    /// Register a tool executor.
    ///
    /// Returns `Err` if a tool with the same `id` is already registered.
    fn register(&self, executor: Arc<dyn ToolExecutor>) -> Result<(), RegistrationError>;

    /// Look up a registered tool executor by its identifier string
    /// (e.g. `"fs.read"`).
    fn get_executor(&self, tool_id: &str) -> Option<Arc<dyn ToolExecutor>>;

    /// Return descriptors for all registered tools.
    fn descriptors(&self) -> Vec<ToolDescriptor>;
}

/// HashMap-backed concrete implementation.
pub struct SimpleToolRegistry {
    tools: Mutex<HashMap<ToolId, (ToolDescriptor, Arc<dyn ToolExecutor>)>>,
}

impl SimpleToolRegistry {
    /// Create an empty registry.
    pub fn new() -> Self {
        Self {
            tools: Mutex::new(HashMap::new()),
        }
    }

    /// Register a tool executor and its descriptor.
    ///
    /// Returns `Err` if a tool with the same `id` is already registered.
    pub fn register_tool(
        &self,
        executor: Arc<dyn ToolExecutor>,
    ) -> Result<(), RegistrationError> {
        let descriptor = executor.descriptor();
        let mut tools = self.tools.lock().unwrap();
        if tools.contains_key(&descriptor.id) {
            return Err(RegistrationError::DuplicateToolId(descriptor.id));
        }
        tools.insert(descriptor.id.clone(), (descriptor, executor));
        Ok(())
    }

    /// Look up a registered tool executor by ID.
    pub fn get_executor(&self, tool_id: &str) -> Option<Arc<dyn ToolExecutor>> {
        let tools = self.tools.lock().unwrap();
        tools.get(tool_id).map(|(_, executor)| executor.clone())
    }

    /// Return descriptors for all registered tools (for model-facing
    /// registration).
    pub fn descriptors(&self) -> Vec<ToolDescriptor> {
        let tools = self.tools.lock().unwrap();
        tools
            .values()
            .map(|(descriptor, _)| descriptor.clone())
            .collect()
    }

    /// Check whether a tool ID is registered.
    pub fn contains(&self, tool_id: &str) -> bool {
        let tools = self.tools.lock().unwrap();
        tools.contains_key(tool_id)
    }
}

#[async_trait]
impl ToolRegistry for SimpleToolRegistry {
    fn register(&self, executor: Arc<dyn ToolExecutor>) -> Result<(), RegistrationError> {
        self.register_tool(executor)
    }

    fn get_executor(&self, tool_id: &str) -> Option<Arc<dyn ToolExecutor>> {
        self.get_executor(tool_id)
    }

    fn descriptors(&self) -> Vec<ToolDescriptor> {
        self.descriptors()
    }
}

/// Errors that can occur when registering a tool.
#[derive(Debug, thiserror::Error)]
pub enum RegistrationError {
    /// A tool with the same ID is already registered.
    #[error("tool with id '{0}' is already registered")]
    DuplicateToolId(ToolId),
}

impl Default for SimpleToolRegistry {
    fn default() -> Self {
        Self::new()
    }
}

