/// Input for the `fs.edit` tool.
#[derive(Debug, Clone, Deserialize, JsonSchema)]
pub struct EditInput {
    /// Relative path of the file to write.
    pub path: String,
    /// The new full content of the file (whole-file replacement, not a diff).
    pub content: String,
}

/// Replaces an entire file in the workspace with new content.
///
/// Phase 4 uses whole-file replacement. Patch/diff support is deferred to a
/// later phase to keep the tool surface minimal.
pub struct EditTool {
    workspace: Arc<dyn Workspace>,
}

impl EditTool {
    pub fn new(workspace: Arc<dyn Workspace>) -> Self {
        Self { workspace }
    }
}

impl EditTool {
    fn descriptor() -> ToolDescriptor {
        ToolDescriptor {
            id: "fs.edit".to_string(),
            name: "fs.edit".to_string(),
            description: "Replace the contents of a file in the workspace".to_string(),
            input_schema: serde_json::to_value(
                <EditInput as JsonSchema>::json_schema()
            ).unwrap_or(serde_json::json!({})),
        }
    }
}

#[async_trait::async_trait]
impl ToolExecutor for EditTool {
    fn descriptor(&self) -> ToolDescriptor {
        Self::descriptor()
    }

    async fn execute(
        &self,
        input: serde_json::Value,
        token: CancellationToken,
    ) -> ExecutionResult {
        let input: EditInput = match serde_json::from_value(input) {
            Ok(v) => v,
            Err(e) => {
                return ExecutionResult {
                    success: false,
                    content: String::new(),
                    failure: Some(harness_tools::ExecutionFailure {
                        kind: harness_tools::FailureKind::InvalidInput,
                        message: e.to_string(),
                    }),
                    usage: None,
                };
            }
        };

        if token.is_cancelled() {
            return ExecutionResult::cancelled();
        }

        info!(path = %input.path, "fs.edit: writing file");

        match self.workspace.write(&input.path, &input.content).await {
            Ok(()) => ExecutionResult {
                success: true,
                content: format!("Successfully wrote {} ({} bytes)", input.path, input.content.len()),
                failure: None,
                usage: None,
            },
            Err(e) => ExecutionResult {
                success: false,
                content: String::new(),
                failure: Some(harness_tools::ExecutionFailure {
                    kind: harness_tools::FailureKind::WorkspaceError,
                    message: e.to_string(),
                }),
                usage: None,
            },
        }
    }
}

