#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use harness_core::capabilities::{AgentCapabilities, WorkspaceCapabilities};
    use harness_protocol::backend::BackendCapabilities;
    use harness_protocol::ids::ToolId;
    use harness_protocol::tools::{
        AgentToolset, PermissionMode, ToolCapability, ToolDescriptor, ToolPolicy,
    };

    use super::*;

    /// Helper to build an `AgentCapabilities` with one tool of the given
    /// permission mode and enabled state.
    fn capabilities_with_tool(
        tool_name: &str,
        permission: PermissionMode,
        enabled: bool,
    ) -> AgentCapabilities {
        let id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id,
                    name: tool_name.to_string(),
                    description: String::new(),
                    input_schema: serde_json::json!({}),
                },
                policy: harness_protocol::tools::ToolPolicy {
                    permission,
                    enabled,
                },
                delegatable: false,
            },
        );
        AgentCapabilities {
            tools: AgentToolset { tools },
            can_spawn_agents: false,
            max_child_depth: None,
            workspace: WorkspaceCapabilities {
                can_read: false,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities::default(),
        }
    }

    #[test]
    fn allow_enabled_tool_returns_allow() {
        let caps = capabilities_with_tool("fs.read", PermissionMode::Allow, true);
        let outcome = PermissionPolicy.evaluate(&caps, "fs.read");
        assert!(matches!(outcome, PermissionOutcome::Allow));
    }

    #[test]
    fn ask_tool_returns_requires_approval() {
        let caps = capabilities_with_tool("bash.exec", PermissionMode::Ask, true);
        let outcome = PermissionPolicy.evaluate(&caps, "bash.exec");
        assert!(matches!(outcome, PermissionOutcome::RequiresApproval(_)));
    }

    #[test]
    fn deny_tool_is_denied() {
        let caps = capabilities_with_tool("dangerous.write", PermissionMode::Deny, true);
        let outcome = PermissionPolicy.evaluate(&caps, "dangerous.write");
        assert!(matches!(outcome, PermissionOutcome::Denied(_)));
    }

    #[test]
    fn disabled_tool_is_denied_even_when_allow() {
        let caps = capabilities_with_tool("disabled.tool", PermissionMode::Allow, false);
        let outcome = PermissionPolicy.evaluate(&caps, "disabled.tool");
        assert!(matches!(outcome, PermissionOutcome::Denied(_)));
    }

    #[test]
    fn unknown_tool_is_denied() {
        let caps = capabilities_with_tool("known.tool", PermissionMode::Allow, true);
        let outcome = PermissionPolicy.evaluate(&caps, "unknown.tool");
        assert!(matches!(outcome, PermissionOutcome::Denied(_)));
    }

    #[test]
    fn empty_toolset_denies_everything() {
        let caps = AgentCapabilities {
            tools: AgentToolset {
                tools: HashMap::new(),
            },
            can_spawn_agents: false,
            max_child_depth: None,
            workspace: WorkspaceCapabilities {
                can_read: false,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities::default(),
        };
        let outcome = PermissionPolicy.evaluate(&caps, "anything");
        assert!(matches!(outcome, PermissionOutcome::Denied(_)));
    }
}

use std::sync::Arc;

use schemars::JsonSchema;
use serde::Deserialize;
use tracing::info;

use harness_tools::{
    CancellationToken, ExecutionFailure, ExecutionResult, FailureKind, ToolDescriptor, ToolExecutor,
};
use harness_workspace::Workspace;

/// Input for the `workspace.search` tool.
#[derive(Debug, Clone, Deserialize, JsonSchema)]
pub struct SearchInput {
    /// The search query (case-insensitive substring match).
    pub query: String,
}

/// Searches all text files in the workspace for the given query.
///
/// Delegates to [`Workspace::search`] and formats the results into a
/// human-readable `ExecutionResult`.
#[derive(Clone)]
pub struct SearchTool {
    workspace: Arc<dyn Workspace>,
}

impl SearchTool {
    pub fn new(workspace: Arc<dyn Workspace>) -> Self {
        Self { workspace }
    }
}

impl SearchTool {
    fn descriptor() -> ToolDescriptor {
        ToolDescriptor {
            id: "workspace.search".to_string(),
            name: "workspace.search".to_string(),
            description: "Search all text files in the workspace for a query string".to_string(),
            input_schema: serde_json::to_value(<SearchInput as JsonSchema>::json_schema())
                .unwrap_or(serde_json::json!({})),
        }
    }
}

#[async_trait::async_trait]
impl ToolExecutor for SearchTool {
    fn descriptor(&self) -> ToolDescriptor {
        Self::descriptor()
    }

    async fn execute(
        &self,
        input: serde_json::Value,
        token: CancellationToken,
    ) -> ExecutionResult {
        let input: SearchInput = match serde_json::from_value(input) {
            Ok(v) => v,
            Err(e) => {
                return ExecutionResult {
                    success: false,
                    content: String::new(),
                    failure: Some(ExecutionFailure {
                        kind: FailureKind::InvalidInput,
                        message: e.to_string(),
                    }),
                    usage: None,
                };
            }
        };

        if token.is_cancelled() {
            return ExecutionResult::cancelled();
        }

        info!(query = %input.query, "workspace.search: searching");

        match self.workspace.search(&input.query).await {
            Ok(result) => {
                let content = if result.matches.is_empty() {
                    format!("No matches found for query '{}'", input.query)
                } else {
                    let mut lines = vec![format!(
                        "{} matches found for '{}':",
                        result.total_count, input.query
                    )];
                    for m in &result.matches {
                        let rel = m.file_path.display();
                        lines.push(format!("  {}:{}: {}", rel, m.line_number, m.line_content));
                    }
                    lines.join("\n")
                };
                ExecutionResult {
                    success: true,
                    content,
                    failure: None,
                    usage: None,
                }
            }
            Err(e) => ExecutionResult {
                success: false,
                content: String::new(),
                failure: Some(ExecutionFailure {
                    kind: FailureKind::WorkspaceError,
                    message: e.to_string(),
                }),
                usage: None,
            },
        }
    }
}

use std::path::{Path, PathBuf};
use std::sync::Arc;

use futures::StreamExt;
use tokio::fs;
use tokio::io::AsyncReadExt;
use tracing::warn;
use serde::Serialize;

/// Controls how workspace instances observe each other's writes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum WorkspaceMode {
    /// Multiple handles on the same root see each other's writes (default).
    #[default]
    Shared,
    /// Writes from one handle are invisible to others (stub — returns errors).
    Isolated,
}

#[derive(thiserror::Error, Debug)]
pub enum WorkspaceError {
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    #[error("Path outside workspace root: {path}")]
    PathTraversal { path: PathBuf },

    #[error("Isolated workspace does not support this operation")]
    Isolated,

    #[error("Tool execution failed: {0}")]
    ToolFailed(String),
}

/// Represents a single search match.
#[derive(Debug, Clone, Serialize)]
pub struct SearchMatch {
    pub file_path: PathBuf,
    pub line_number: usize,
    pub line_content: String,
}

/// Result of a workspace search operation.
#[derive(Debug, Clone, Serialize)]
pub struct SearchResult {
    pub matches: Vec<SearchMatch>,
    pub total_count: usize,
}

/// Metadata about a file in the workspace.
#[derive(Debug, Clone, Serialize)]
pub struct FileInfo {
    pub path: PathBuf,
    pub size_bytes: u64,
    pub is_directory: bool,
}

/// Progress event emitted during long-running tool operations.
#[derive(Debug, Clone, Serialize)]
pub struct ToolProgress {
    pub tool_call_id: String,
    pub phase: ProgressPhase,
    pub message: String,
}

#[derive(Debug, Clone, Serialize)]
pub enum ProgressPhase {
    Started,
    Streaming,
    Completed,
    Failed,
}

/// Result of a tool execution.
#[derive(Debug, Clone, Serialize)]
pub struct ToolResult {
    pub tool_call_id: String,
    pub success: bool,
    pub content: String,
}

/// Abstract workspace access for tools.
#[async_trait::async_trait]
pub trait Workspace: Send + Sync {
    fn root(&self) -> &Path;
    fn mode(&self) -> WorkspaceMode;

    /// Read a file relative to the workspace root.
    async fn read(&self, relative_path: &str) -> Result<String, WorkspaceError>;

    /// Write (replace) a file relative to the workspace root.
    async fn write(&self, relative_path: &str, content: &str) -> Result<(), WorkspaceError>;

    /// Search for `query` (case-insensitive substring) in all UTF-8 text files.
    async fn search(&self, query: &str) -> Result<SearchResult, WorkspaceError>;

    /// List files recursively (up to `max_depth`, 0 = unlimited).
    async fn list_files(&self, max_depth: usize) -> Result<Vec<FileInfo>, WorkspaceError>;
}

/// A workspace stub that pretends writes are invisible to other handles.
/// Permits reads; rejects writes with [`WorkspaceError::Isolated`].
///
/// In a future phase this will be backed by a temporary copy-on-write
/// tree. For now it exists to satisfy the capability surface.
pub struct IsolatedWorkspace {
    inner: Arc<dyn Workspace>,
}

impl IsolatedWorkspace {
    pub fn new(inner: Arc<dyn Workspace>) -> Self {
        Self { inner }
    }
}

#[async_trait::async_trait]
impl Workspace for IsolatedWorkspace {
    fn root(&self) -> &Path {
        self.inner.root()
    }

    fn mode(&self) -> WorkspaceMode {
        WorkspaceMode::Isolated
    }

    async fn read(&self, relative_path: &str) -> Result<String, WorkspaceError> {
        self.inner.read(relative_path).await
    }

    async fn write(&self, _relative_path: &str, _content: &str) -> Result<(), WorkspaceError> {
        Err(WorkspaceError::Isolated)
    }

    async fn search(&self, query: &str) -> Result<SearchResult, WorkspaceError> {
        self.inner.search(query).await
    }

    async fn list_files(&self, max_depth: usize) -> Result<Vec<FileInfo>, WorkspaceError> {
        self.inner.list_files(max_depth).await
    }
}

#[cfg(test)]
mod isolated_tests {
    use super::*;
    use tempfile::tempdir;

    #[tokio::test]
    async fn isolated_workspace_allows_reads() {
        let dir = tempdir().unwrap();
        fs::write(dir.path().join("data.txt"), "secret").await.unwrap();

        let shared = crate::FsWorkspace::new(dir.path().to_path_buf());
        let isolated = IsolatedWorkspace::new(Arc::new(shared));

        let contents = isolated.read("data.txt").await.unwrap();
        assert_eq!(contents, "secret");
    }

    #[tokio::test]
    async fn isolated_workspace_rejects_writes() {
        let dir = tempdir().unwrap();
        let shared = crate::FsWorkspace::new(dir.path().to_path_buf());
        let isolated = IsolatedWorkspace::new(Arc::new(shared));

        let result = isolated.write("data.txt", "new content").await;
        assert!(matches!(result, Err(WorkspaceError::Isolated)));
    }
}
